mapper.select:
SELECT id, prompt_id, agent_id, node_code, prompt_version, content_ref, enabled, created_at, updated_at
FROM agent_node_prompt
WHERE agent_id = #{agentId}
  AND node_code = #{nodeCode}
  AND enabled = 1
ORDER BY updated_at DESC

SELECT id, prompt_id, agent_id, node_code, prompt_version, content_ref, enabled, created_at, updated_at
FROM agent_node_prompt
WHERE agent_id = #{agentId}
  AND node_code = #{nodeCode}
  AND prompt_version = #{promptVersion}
LIMIT 1
